import React, { Component } from "react";
import "./LoginModal.css";

export default class LoginModal extends Component {
  constructor(props) {
    super(props);
    this.state = {
      activeTab: "Sign up",
      formData: {},
      loginFormData: {},
    };
  }

  setActiveTab = (tab) => {
    this.setState({ activeTab: tab });
  };

  handleChange = (e) => {
    const { name, value } = e.target;
    this.setState((prevState) => ({
      formData: {
        ...prevState.formData,
        [name]: value
      },
      loginFormData: {
        ...prevState.loginFormData,
        [name]: value
      }
    }));
  };

  render() {
    const { activeTab, formData, loginFormData } = this.state;

    return (
      <div className={`modal ${this.props.show ? 'show' : ''}`}>
        <div className="modal-content">
          <span className="close" onClick={this.props.onClose}>&times;</span>
          <div className="formboxx">
            <div className="button-boxx">
              <button
                className={`toggle-btn1 ${activeTab === "Log in" ? "active" : ""}`}
                onClick={() => this.setActiveTab("Log in")}
              >
                Log In
              </button>
              <button
                className={`toggle-btn1 ${activeTab === "Sign up" ? "active" : ""}`}
                onClick={() => this.setActiveTab("Sign up")}
              >
                Sign Up
              </button>
            </div>

            {activeTab === "Sign up" && (
              <form className="input-group">
                <input
                  type="text"
                  className="input-field"
                  placeholder="Username"
                  name="username"
                  value={formData.username || ""}
                  onChange={this.handleChange}
                  required
                />
                <input
                  type="email"
                  className="input-field"
                  placeholder="Email"
                  name="email"
                  value={formData.email || ""}
                  onChange={this.handleChange}
                  required
                />
                <input
                  type="password"
                  className="input-field"
                  placeholder="Password"
                  name="password"
                  value={formData.password || ""}
                  onChange={this.handleChange}
                  required
                />
                <button type="submit" className="submit-btnn">Sign up</button>
              </form>
            )}

            {activeTab === "Log in" && (
              <form className="input-group_login">
                <input
                  type="text"
                  className="input-field1_login"
                  placeholder="Username"
                  name="loginUsername"
                  value={loginFormData.loginUsername || ""}
                  onChange={this.handleChange}
                  required
                />
                <input
                  type="password"
                  className="input-field1_login"
                  placeholder="Password"
                  name="loginPassword"
                  value={loginFormData.loginPassword || ""}
                  onChange={this.handleChange}
                  required
                />
                <button type="submit" className="submit-btnn">Log in</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }
}
